function Row({ label, value, isPercent, isNegativeHighlight, isPlainNumber }) {
  return (
    <div
      style={{
        display: "flex",
        justifyContent: "space-between",
        padding: "10px 16px",
        borderBottom: "1px solid #e5e7eb",
        background: "#fff",
      }}
    >
      <div style={{ color: "#374151" }}>{label}</div>

      <div
        style={{
          fontWeight: "600",
          color: isNegativeHighlight ? "#dc2626" : "#111827",
        }}
      >
        {isPercent
          ? `%${Number(value || 0).toFixed(1)}`
          : isPlainNumber
            ? formatNumber(value || 0)
            : formatMoneyByCurrency(value || 0, "TRY")}
      </div>
    </div>
  );
}

const API_BASE = import.meta.env.VITE_API_BASE || "http://localhost:5001";

// ── GLOBAL FETCH INTERCEPTOR (multi-tenant izolasyon güvenliği) ──────────────
// Backend, isteğin hangi firmaya (tenant) ait olduğunu JWT'den çözer. Eğer bir
// API çağrısı token taşımazsa backend public (ERC) şemasına düşer — bu, izole
// bir firma oturumunda ERC verisinin sızması demektir. Frontend'de yüzlerce
// dağınık fetch çağrısı token göndermiyor. Bu interceptor, API_BASE'e giden ve
// Authorization başlığı OLMAYAN tüm isteklere mevcut token'ı otomatik ekler.
// ERC kullanıcısı için token.tenant='erc' → backend hiçbir şey yapmaz (davranış
// birebir aynı). Açıkça finance_token gönderen çağrılara dokunulmaz.
if (typeof window !== "undefined" && !window.__omnixFetchPatched) {
  window.__omnixFetchPatched = true;
  const _origFetch = window.fetch.bind(window);
  window.fetch = (input, init) => {
    try {
      const url = typeof input === "string" ? input : (input && input.url) || "";
      if (url && url.indexOf(API_BASE) === 0) {
        const opts = init ? { ...init } : {};
        const headers = new Headers(opts.headers || (typeof input !== "string" && input.headers) || {});
        if (!headers.has("Authorization")) {
          const tk = localStorage.getItem("token");
          if (tk) {
            headers.set("Authorization", `Bearer ${tk}`);
            opts.headers = headers;
            return _origFetch(input, opts);
          }
        }
      }
    } catch { /* sessizce orijinal davranışa düş */ }
    return _origFetch(input, init);
  };
}

function normalizeCurrency(value) {
  const raw = String(value || "")
    .trim()
    .toUpperCase();
  if (raw === "USD" || raw === "$" || raw.includes("USD")) return "USD";
  return "TRY";
}

function findPaymentInfoByInvoiceNo(paymentMap, invoiceNo, currency) {
  const cleanInvoiceNo = String(invoiceNo || "").trim();
  const cleanCurrency = String(currency || "")
    .trim()
    .toUpperCase();

  if (!cleanInvoiceNo) return null;

  // birebir eşleşme
  if (paymentMap.has(cleanInvoiceNo)) {
    return paymentMap.get(cleanInvoiceNo);
  }

  // USD ise -cur'lı halini de kontrol et
  if (cleanCurrency === "USD") {
    const curVersion = `${cleanInvoiceNo}-cur`;
    if (paymentMap.has(curVersion)) {
      return paymentMap.get(curVersion);
    }
  }

  // invoice_no zaten -cur ile geldiyse normal halini de kontrol et
  if (cleanInvoiceNo.toLowerCase().endsWith("-cur")) {
    const normalVersion = cleanInvoiceNo.replace(/-cur$/i, "");
    if (paymentMap.has(normalVersion)) {
      return paymentMap.get(normalVersion);
    }
  }

  return null;
}

function formatMoneyByCurrency(value, currency = "TRY") {
  const safeCurrency = normalizeCurrency(currency);

  return new Intl.NumberFormat("tr-TR", {
    style: "currency",
    currency: safeCurrency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 0,
  }).format(Number(value || 0));
}

function formatDateOnly(value) {
  if (!value) return "";

  const str = String(value).trim();

  if (/^\d{4}-\d{2}-\d{2}$/.test(str)) {
    const [year, month, day] = str.split("-");
    return `${day}.${month}.${year}`;
  }

  const parsed = new Date(str);
  if (!Number.isNaN(parsed.getTime())) {
    const day = String(parsed.getDate()).padStart(2, "0");
    const month = String(parsed.getMonth() + 1).padStart(2, "0");
    const year = parsed.getFullYear();
    return `${day}.${month}.${year}`;
  }

  return str;
}
// ─── Brüt Maaş Hesaplama (2026 Türkiye) ─────────────────────────────────────
// Net = Brüt × (1 - SGK İşçi 14% - İşsizlik İşçi 1% - Gelir+Damga ~15%)
// Brüt ≈ Net / 0.70
// İşveren maliyeti = Brüt × (1 + SGK İşv 20.5% + İşsizlik İşv 2%)
function calcBrutMaas(netMaas) {
  const net  = Number(netMaas || 0);
  const brut = Math.round(net / 0.70);
  const sgkIssizlikIsci = Math.round(brut * 0.15);   // 14% SGK + 1% İşsizlik
  const gelirDamga      = Math.round(brut - net - sgkIssizlikIsci); // kalan kesinti
  const sgkIssizlikIsv  = Math.round(brut * 0.225);  // 20.5% SGK + 2% İşsizlik
  const isverenMaliyet  = brut + sgkIssizlikIsv;
  return { brut, sgkIssizlikIsci, gelirDamga, sgkIssizlikIsv, isverenMaliyet };
}

function BordroOzeti({ bankadan, elden }) {
  const b = Number(bankadan || 0);
  const e = Number(elden || 0);
  if (b <= 0 && e <= 0) return null;
  // Vergi hesabı yalnızca bankadan yatırılan kısım üzerinden
  const brut              = Math.round(b / 0.70);
  const sgkIssizlikIsci   = Math.round(brut * 0.15);
  const gelirDamga        = Math.round(brut - b - sgkIssizlikIsci);
  const sgkIssizlikIsv    = Math.round(brut * 0.225);
  const bankaIsverenMal   = brut + sgkIssizlikIsv;
  const toplamIsverenMal  = bankaIsverenMal + e;
  const TL = (n) => `₺${Number(n).toLocaleString("tr-TR")}`;
  const R = ({ label, val, color, bg, bold, indent }) => (
    <div style={{ display:"flex", justifyContent:"space-between", padding:"5px 10px", fontSize:"12px", background: bg||"transparent" }}>
      <span style={{ color:"#374151", fontWeight: bold?700:400, paddingLeft: indent?"10px":"0" }}>{label}</span>
      <span style={{ fontWeight:700, color: color||"#374151" }}>{val}</span>
    </div>
  );
  const Sep = ({ label }) => (
    <div style={{ padding:"4px 10px", fontSize:"11px", color:"#6b7280", fontStyle:"italic", borderTop:"1px solid #f0fdf4" }}>{label}</div>
  );
  return (
    <div style={{ background:"linear-gradient(135deg,#f0fdf4,#ecfdf5)", border:"1.5px solid #86efac", borderRadius:"12px", padding:"12px 16px", marginBottom:"12px" }}>
      <div style={{ fontSize:"12px", fontWeight:700, color:"#065f46", marginBottom:"8px" }}>📊 Bordro Özeti (Tahmini)</div>
      <div style={{ background:"#fff", borderRadius:"8px", overflow:"hidden", border:"1px solid #d1fae5" }}>
        {b > 0 && <>
          <R label="Brüt Maaş (bankadan kısım)" val={TL(brut)} color="#1e40af" bg="#f0fdf4" bold />
          <Sep label="Çalışan Kesintileri" />
          <R label="SGK + İşsizlik İşçi (%15)" val={`- ${TL(sgkIssizlikIsci)}`} color="#dc2626" indent />
          <R label="Gelir + Damga Vergisi" val={`- ${TL(gelirDamga)}`} color="#dc2626" indent />
          <R label="Net Bankadan Ödeme" val={TL(b)} color="#166534" bg="#f0fdf4" bold />
          <Sep label="İşveren Yükümlülüğü (Bankadan)" />
          <R label="SGK + İşsizlik İşveren (%22.5)" val={`+ ${TL(sgkIssizlikIsv)}`} color="#92400e" indent />
        </>}
        {e > 0 && <>
          <Sep label="Elden Ödeme (vergisiz — iş avansı mantığı)" />
          <R label="💵 Elden Verilen" val={TL(e)} color="#7c3aed" bg="#faf5ff" bold />
        </>}
        <div style={{ display:"flex", justifyContent:"space-between", padding:"7px 10px", fontSize:"12px", background:"#fef3c7", borderTop:"1px solid #fde68a" }}>
          <span style={{ color:"#78350f", fontWeight:700 }}>🏛️ Toplam İşveren Maliyeti</span>
          <span style={{ fontWeight:800, color:"#b45309" }}>{TL(toplamIsverenMal)}</span>
        </div>
      </div>
    </div>
  );
}

