function getQtyAnalysis(doneQty, requestedQty) {
  const done = Number(doneQty || 0);
  const requested = Number(requestedQty || 0);

  if (requested === 0 && done > 0) {
    return {
      diff: "-",
      label: "PO Bekliyor",
      className: "analysis-waiting",
    };
  }

  const diff = done - requested;

  if (diff === 0) {
    return {
      diff: 0,
      label: "Tamam",
      className: "analysis-complete",
    };
  }

  if (diff < 0) {
    return {
      diff,
      label: "Eksik",
      className: "analysis-missing",
    };
  }

  return {
    diff,
    label: "Fazla",
    className: "analysis-over",
  };
}

function getRegion(siteCode = "", projectCode = "") {
  const code = String(siteCode || "")
    .trim()
    .toUpperCase();
  const project = String(projectCode || "")
    .trim()
    .toUpperCase();

  if (
    code.startsWith("ES") ||
    code.startsWith("BO") ||
    code.startsWith("ZO") ||
    code.startsWith("KA") ||
    code.startsWith("BI") ||
    code.startsWith("AN") ||
    code.startsWith("CN") ||
    code.includes("_ANK")
  ) {
    return "Ankara";
  }

  if (
    code.startsWith("IZ") ||
    code.startsWith("US") ||
    code.startsWith("MU") ||
    code.startsWith("MN") ||
    code.startsWith("AI") ||
    code.startsWith("DE") ||
    code.includes("_IZM")
  ) {
    return "İzmir";
  }

  if (
    code.startsWith("AT") ||
    code.startsWith("IP") ||
    code.startsWith("BU") ||
    code.startsWith("AF") ||
    code.includes("_ANT")
  ) {
    return "Antalya";
  }

  // Project code üzerinden yedek bölge tahmini
  if (project.includes("ANK")) return "Ankara";
  if (project.includes("IZM") || project.includes("IZ")) return "İzmir";
  if (project.includes("ANT")) return "Antalya";

  return "Tanımsız";
}

