      if (data) setBankaForm({ banka_adi: data.banka_adi||"", sube: data.sube||"", hesap_no: data.hesap_no||"", iban: data.iban||"", hesap_sahibi: data.hesap_sahibi||"", aciklama: data.aciklama||"" });
